// Gather all reference fields that may contain Drive PDF URLs
const fields = [
  $('Map Form Data').item.json.brand_guidelines_refs || '',
  $('Map Form Data').item.json.banner_guidelines_refs || '',
  $('Map Form Data').item.json.competitor_refs || ''
];

const combined = fields.join(' ; ');
const tokens = combined.split(/[;,\s\n]+/).filter(t => t.trim().length > 0);

const references = [];
for (const token of tokens) {
  const url = token.trim();
  if (!url.startsWith('http')) continue;

  // Only download Drive files (PDFs/DOCX). Non-Drive URLs (competitor sites) are noted but not downloaded.
  if (url.includes('drive.google.com')) {
    const match = url.match(/[-\w]{25,}/);
    const file_id = match ? match[0] : null;
    if (!file_id) continue;
    references.push({ json: { url, type: 'drive_file', file_id } });
  }
}

// Always return at least one item so flow never stops
if (references.length === 0) {
  return [{ json: { url: '', type: 'none', file_id: null } }];
}

return references;

