// Combine all crawled pages into one clean markdown string
const results = $json.data || [];
const crawlStatus = $json.status || 'unknown';

// If crawl failed or returned nothing
if (results.length === 0) {
  return [{
    json: {
      scraped_markdown: 'Crawl returned no usable content.',
      pages_crawled: 0,
      crawl_status: crawlStatus
    }
  }];
}

// Skip patterns based on CONTENT TYPE not client-specific URLs
// These are universally useless pages across any website
const skipPatterns = [
  '/cart',
  '/checkout',
  '/account',
  '/login',
  '/register',
  '/password',
  '/search',
  '/404',
  'agents.md',
  '.xml',
  '.txt',
  '.json'
];

const combined = results
  // Skip universally useless page types
  .filter(page => {
    const url = (page.metadata?.url || page.url || '').toLowerCase();
    return !skipPatterns.some(pattern => url.includes(pattern));
  })
  // Only keep pages with meaningful content (raised threshold)
  .filter(page => page.markdown && page.markdown.length > 300)
  .map(page => {
    const url = page.metadata?.url || page.url || 'unknown page';
    const content = (page.markdown || '')
      // Remove image markdown but keep alt text
      .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
      // Remove bare URLs not inside markdown links
      .replace(/(?<!\()https?:\/\/\S+(?!\))/g, '')
      // Remove skip to content navigation
      .replace(/\[Skip to content\]\([^)]*\)/gi, '')
      // Remove media gallery notices
      .replace(/Open (featured )?media \d+ in gallery view/gi, '')

      // === CART BOILERPLATE REMOVAL (improved) ===
      .replace(/There.{0,5}s nothing in your cart yet/gi, '')
      .replace(/\byet\n+Loading\.\.\./gi, '')
      .replace(/Order special instructions[\s\S]{0,300}?View Cart[^\n]*/gi, '')
      .replace(/\$0\.00\s*USD\n[\s\S]{0,150}?calculated at checkout/gi, '')
      .replace(/Checkout\s+\[View Cart\][^\n]*/gi, '')
      .replace(/Loading\.\.\./gi, '')
      .replace(/\*\s+\.\s*$/gm, '')
      .replace(/\[Start Shopping\][^\n]*/gi, '')
      .replace(/Taxes and[^\n]*calculated at checkout/gi, '')
      .replace(/Choosing a selection results in a full page refresh/gi, '')
      // Remove orphaned cart header and list items
      .replace(/^Cart\s+\d+\s*[-]*\s*$/gm, '')
      .replace(/^-{3,}\s*$/gm, '')
      .replace(/^\*\s+\.\s*$/gm, '')
      // Remove e-commerce pricing patterns
      .replace(/Regular price[\s\S]{0,80}?Sale price/gi, '')
      .replace(/Unit price[^\n]*/gi, '')
      .replace(/Variant sold out or unavailable/gi, '')
      .replace(/Decrease quantity for[^\n]*/gi, '')
      .replace(/Increase quantity for[^\n]*/gi, '')
      .replace(/Add to Cart\s*\n/gi, '')
      .replace(/Buy it now\s*\n/gi, '')

      // Remove copyright and footer junk
      .replace(/all rights reserved.*?(\n|$)/gi, '')
      .replace(/©\s*\d{4}.*?(\n|$)/g, '')
      .replace(/privacy policy.*?terms.*?(\n|$)/gi, '')
      .replace(/cookie.*?(accept|decline|manage).*?(\n|$)/gi, '')

      // Remove social share buttons
      .replace(/share (on|this|via)[^\n]*/gi, '')

      // Remove WordPress pixel tracker
      .replace(/.*pixel\.wp\.com.*?(\n|$)/g, '')

      // Remove repeated achievement/stat placeholders
      .replace(/^00\s*$/gm, '')

      // Collapse excessive blank lines and spaces
      .replace(/\n{3,}/g, '\n\n')
      .replace(/[ \t]{2,}/g, ' ')
      .trim()
      // Cap each page at 2500 chars
      .substring(0, 2500);

    return `## Page: ${url}\n\n${content}`;
  })
  // Remove pages that became too short after cleaning (raised threshold)
  .filter(page => page.length > 200)
  .join('\n\n---\n\n')
  // Cap total at 14000 chars
  .substring(0, 14000);

return [{
  json: {
    scraped_markdown: combined || 'Crawl returned no usable content after cleaning.',
    pages_crawled: results.length,
    crawl_status: crawlStatus
  }
}];
